        min_clear_width: float | None | Unset = UNSET,
        min_length: float | None | Unset = UNSET,
        min_width: float | None | Unset = UNSET,
        profiles: Sequence[str] | Unset = UNSET,
        within: ArchAuditWithin | None | Unset = UNSET,
